import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';
import {STRUCTURE_TREE,FIXTURES,NOTE_FIXTURES} from './adapters/library-fixtures.js';

const bundle={initialDocumentId:'KU-D05-0021',STRUCTURE_TREE,FIXTURES,NOTE_FIXTURES};
const assert=(condition,message)=>{if(!condition)throw Error(message)};
const ids=adapter=>adapter.snapshot().blocks.map(block=>block.id);
const run=(id,fn)=>{try{return {id,status:'PASS',evidence:fn()}}catch(error){return {id,status:'FAIL',error:String(error?.stack||error)}}};

export function runW4DStructuredDragDropProof(){
  const cases=[];
  cases.push(run('w4d.real-library-learn-consumers',()=>{const library=createStructuredConsumerAdapter('library',bundle),learn=createStructuredConsumerAdapter('learn');assert(library.dragDropOwner.owner==='StructuredDragDropOwner'&&learn.dragDropOwner.owner==='StructuredDragDropOwner','drag owner not shared');assert(library.dropTargetOwner.owner==='StructuredDropTargetPolicyOwner'&&learn.dropTargetOwner.owner===library.dropTargetOwner.owner,'target owner not shared');assert(library.descriptor().dragDropOwner==='StructuredDragDropOwner'&&learn.descriptor().dropTargetOwner==='StructuredDropTargetPolicyOwner','adapter descriptor missing owner truth');return {libraryOwner:library.dragDropOwner.owner,learnOwner:learn.dragDropOwner.owner,targetOwner:library.dropTargetOwner.owner,mutationOwner:library.mutationKernel.owner,transactionOwner:library.transactionOwner.owner};}));
  cases.push(run('w4d.nested-target-identity',()=>{const library=createStructuredConsumerAdapter('library',bundle),v=library.dropTargetOwner.validate('blk-d05-p1',{kind:'gap',parentId:'blk-d05-t1',index:1,depth:1});assert(v.ok&&v.target.parentId==='blk-d05-t1'&&v.targetIdentity==='blk-d05-t1::1::1','nested target identity false');assert(v.parentPathIds.join()==='blk-d05-t1','nested parent path false');return v;}));
  cases.push(run('w4d.self-descendant-invalid-placement-refusal',()=>{const library=createStructuredConsumerAdapter('library',bundle),self=library.dropTargetOwner.validate('blk-d05-t1',{kind:'gap',parentId:'blk-d05-t1',index:0,depth:1}),desc=library.dropTargetOwner.validate('blk-d05-t2',{kind:'gap',parentId:'blk-d05-li1a',index:0,depth:3}),invalid=library.dropTargetOwner.validate('blk-d05-h1',{kind:'gap',parentId:'blk-d05-li1',index:0,depth:2});assert(!self.ok&&self.code==='SELF_DROP','self drop accepted');assert(!desc.ok&&desc.code==='ILLEGAL_DESCENDANT_DROP','descendant drop accepted');assert(!invalid.ok&&invalid.code==='INVALID_CHILD_CONTAINMENT','invalid placement accepted');return {self:self.code,descendant:desc.code,invalidPlacement:invalid.code};}));
  cases.push(run('w4d.autoscroll-and-indicator-presentation-only',()=>{const learn=createStructuredConsumerAdapter('learn'),before=JSON.stringify({doc:learn.snapshot(),tx:learn.transactionDescriptor()}),begin=learn.dragDropOwner.beginPointer({sourceBlockId:'learn-p1',pointerId:7,startX:10,startY:10}),during=learn.dragDropOwner.updatePointer({clientX:30,clientY:196,target:{kind:'gap',parentId:null,index:3,depth:0},viewportTop:0,viewportBottom:200}),after=JSON.stringify({doc:learn.snapshot(),tx:learn.transactionDescriptor()});assert(begin.ok&&during.active&&during.validation.ok,'drag did not activate/validate');assert(during.autoscroll.direction==='down'&&during.autoscroll.deltaY>0&&during.autoscroll.derived,'autoscroll projection false');assert(during.indicator.visible&&during.indicator.valid&&during.indicator.derived,'indicator projection false');assert(before===after,'presentation projection mutated document truth');learn.dragDropOwner.cancelPointer('proof');return {autoscroll:during.autoscroll,indicator:during.indicator,documentTruthUnchanged:true};}));
  cases.push(run('w4d.pointer-atomic-mutation-undo',()=>{const learn=createStructuredConsumerAdapter('learn'),before=learn.snapshot(),beforeTx=learn.transactionDescriptor();learn.dragDropOwner.beginPointer({sourceBlockId:'learn-p1',pointerId:11,startX:0,startY:0});const update=learn.dragDropOwner.updatePointer({clientX:20,clientY:20,target:{kind:'gap',parentId:null,index:3,depth:0},viewportTop:0,viewportBottom:800}),result=learn.dragDropOwner.commitPointer();const after=learn.snapshot(),afterTx=learn.transactionDescriptor();assert(update.validation.ok&&result.ok&&result.changed&&result.historyFrameDelta===1,'pointer commit not atomic');assert(after.blocks.at(-1).id==='learn-p1','pointer reorder target false');assert(result.receipt.mutationOwner==='StructuredMutationKernel'&&result.receipt.transactionOwner==='StructuredTransactionHistoryRecoveryOwner','canonical mutation/transaction route false');const undone=learn.undo();assert(undone.changed&&JSON.stringify(learn.snapshot())===JSON.stringify(before),'pointer undo not exact');return {before:before.blocks.map(b=>b.id),after:after.blocks.map(b=>b.id),historyBefore:beforeTx.historyLength,historyAfter:afterTx.historyLength,mutationOwner:result.receipt.mutationOwner,transactionOwner:result.receipt.transactionOwner,undoExact:true};}));
  cases.push(run('w4d.keyboard-shared-target-policy-atomic-undo',()=>{const learn=createStructuredConsumerAdapter('learn'),before=learn.snapshot(),beforeTx=learn.transactionDescriptor(),validation=learn.dropTargetOwner.keyboardTarget('learn-p1','down'),result=learn.dragDropOwner.reorderKeyboard('learn-p1','down'),after=learn.snapshot(),afterTx=learn.transactionDescriptor();assert(validation.ok&&result.validation.ok&&result.validation.owner===validation.owner&&result.targetPolicyOwner==='StructuredDropTargetPolicyOwner','keyboard bypassed target policy');assert(result.ok&&result.changed&&result.historyFrameDelta===1&&after.blocks.at(-1).id==='learn-p1','keyboard reorder failed');learn.undo();assert(JSON.stringify(learn.snapshot())===JSON.stringify(before),'keyboard undo not exact');return {validationOwner:validation.owner,targetIdentity:validation.targetIdentity,before:before.blocks.map(b=>b.id),after:after.blocks.map(b=>b.id),historyBefore:beforeTx.historyLength,historyAfter:afterTx.historyLength,undoExact:true};}));
  cases.push(run('w4d.pointer-keyboard-canonical-policy-parity',()=>{const a=createStructuredConsumerAdapter('learn'),pointer=a.dropTargetOwner.validate('learn-p1',{kind:'gap',parentId:null,index:3,depth:0},{route:'pointer-proof'}),keyboard=a.dropTargetOwner.keyboardTarget('learn-p1','down');assert(pointer.ok&&keyboard.ok&&pointer.owner===keyboard.owner&&pointer.policyRevision===keyboard.policyRevision&&pointer.targetIdentity===keyboard.targetIdentity,'pointer/keyboard target validation diverged');return {owner:pointer.owner,policyRevision:pointer.policyRevision,targetIdentity:pointer.targetIdentity,pointerRoute:'validate',keyboardRoute:'keyboardTarget->validate'};}));
  cases.push(run('w4d.selection-not-owned',()=>{const learn=createStructuredConsumerAdapter('learn');learn.selectBlocks(['learn-p1']);const before=learn.selectedFragmentIdentity(),ownerBefore=learn.selection.owner;learn.dragDropOwner.beginPointer({sourceBlockId:'learn-p1',startX:0,startY:0});learn.dragDropOwner.updatePointer({clientX:20,clientY:20,target:{kind:'gap',parentId:null,index:3,depth:0},viewportTop:0,viewportBottom:500});const during=learn.selectedFragmentIdentity();learn.dragDropOwner.cancelPointer();assert(ownerBefore==='StructuredSelectionKernel'&&during.owner===ownerBefore&&JSON.stringify(before.blockIds)===JSON.stringify(during.blockIds),'drag owner mutated selection truth');return {selectionOwner:ownerBefore,dragOwner:learn.dragDropOwner.owner,unchanged:true};}));
  const pass=cases.filter(x=>x.status==='PASS').length,fail=cases.length-pass;return {schemaVersion:1,kind:'W4_D_STRUCTURED_DRAG_DROP_CORE_PROOF',status:fail?'FAIL':'PASS',pass,fail,cases};
}
